+
+#define SCMI_TDE_VAR_SZ(_t)						       \
+	({								       \
+		struct telemetry_de *__t = _t;				       \
+		size_t _sz = 0;						       \
+									       \
+		_sz += __t->ts_type == TSTAMP_LINE ? sizeof(__le32) : 0;       \
+		_sz += __t->de.fc_support ? sizeof(struct de_desc_fc) : 0;     \
+		_sz += __t->de.name_support ? SCMI_SHORT_NAME_MAX_SIZE : 0;    \
+									       \
