+
+static int qca8k_lag_refresh_conduit_ports(struct dsa_switch *ds,
+					   struct dsa_lag lag)
+{
+	struct dsa_port *dp;
+	int ret;
+
+	dsa_switch_for_each_user_port(dp, ds) {
