-	   It must be helt while manipulating the following registers:
-	   CSR0, CSR6, CSR7, CSR9, CSR10, CSR15
-	 */
-	spinlock_t lock;
-
-	struct pci_dev *pdev;
-	struct net_device *dev;
-};
