-static void xircom_poll_controller(struct net_device *dev)
-{
-	struct xircom_private *xp = netdev_priv(dev);
-	const int irq = xp->pdev->irq;
-
-	disable_irq(irq);
-	xircom_interrupt(irq, dev);
-	enable_irq(irq);
-}
-#endif
