2.51.0

The existing coreboot_table_populate() bounds checks limit individual
entries to the mapped length.
However, coreboot_table_probe() replaces the platform resource length with
header and table sizes supplied by firmware before mapping the full table.

A malformed table can overflow the 32-bit size addition or advertise an
extent beyond the resource, causing the driver to map and parse memory
outside the resource. A resource shorter than the fixed header is also
mapped as though it contained a complete header.

Reject resources shorter than the fixed header. After validating the
signature, require a complete header, calculate the advertised extent with
overflow checking, and reject extents beyond the resource before remapping
the table.

Fixes: d384d6f43d1e ("firmware: google memconsole: Add coreboot support")
Signed-off-by: Laxman Acharya Padhya <acharyalaxman8848@gmail.com>

diff --git a/drivers/firmware/google/coreboot_table.c b/drivers/firmware/google/coreboot_table.c
index e63933ff6..96e68ae3f 100644
--- a/drivers/firmware/google/coreboot_table.c
+++ b/drivers/firmware/google/coreboot_table.c
@@ -170,6 +170,7 @@ static int coreboot_table_populate(struct device *dev, void *ptr, resource_size_
 static int coreboot_table_probe(struct platform_device *pdev)
 {
 	resource_size_t len;
+	resource_size_t table_span;
 	struct coreboot_table_header *header;
 	struct resource *res;
 	struct device *dev = &pdev->dev;
@@ -181,7 +182,7 @@ static int coreboot_table_probe(struct platform_device *pdev)
 		return -EINVAL;
 
 	len = resource_size(res);
-	if (!res->start || !len)
+	if (!res->start || len < sizeof(*header))
 		return -EINVAL;
 
 	/* Check just the header first to make sure things are sane */
@@ -189,19 +190,27 @@ static int coreboot_table_probe(struct platform_device *pdev)
 	if (!header)
 		return -ENOMEM;
 
-	len = header->header_bytes + header->table_bytes;
 	ret = strncmp(header->signature, "LBIO", sizeof(header->signature));
+
+	if (!ret &&
+	    (header->header_bytes < sizeof(*header) ||
+	     check_add_overflow((resource_size_t)header->header_bytes,
+				(resource_size_t)header->table_bytes,
+				&table_span) ||
+	     table_span > len))
+		ret = -EINVAL;
+
 	memunmap(header);
 	if (ret) {
 		dev_warn(dev, "coreboot table missing or corrupt!\n");
 		return -ENODEV;
 	}
 
-	ptr = memremap(res->start, len, MEMREMAP_WB);
+	ptr = memremap(res->start, table_span, MEMREMAP_WB);
 	if (!ptr)
 		return -ENOMEM;
 
-	ret = coreboot_table_populate(dev, ptr, len);
+	ret = coreboot_table_populate(dev, ptr, table_span);
 
 	memunmap(ptr);
 
-- 
2.51.2

load_copro_firmware() reads the image signature and size from a fixed
offset before checking that the firmware contains the corresponding
header.  A truncated firmware file can therefore cause an out-of-bounds
read.  The image size is also used to advance through the blob and to
copy the selected image to the coprocessor without checking that it is
non-zero, large enough for the header, or contained in the firmware
buffer.

Validate the header and image range before reading or copying any image.
This also prevents a zero image size from making the image scan loop
never advance.

Signed-off-by: Laxman Acharya Padhya <acharyalaxman8848@gmail.com>
---
 drivers/fsi/fsi-master-ast-cf.c | 18 +++++++++++++++++-
 1 file changed, 17 insertions(+), 1 deletion(-)

diff --git a/drivers/fsi/fsi-master-ast-cf.c b/drivers/fsi/fsi-master-ast-cf.c
index c3ac76bf7e9..410bd600cd7 100644
--- a/drivers/fsi/fsi-master-ast-cf.c
+++ b/drivers/fsi/fsi-master-ast-cf.c
@@ -831,6 +831,8 @@ static int load_copro_firmware(struct fsi_master_acf *master)
 	const struct firmware *fw;
 	uint16_t sig = 0, wanted_sig;
 	const u8 *data;
+	const u8 *end;
+	const size_t image_hdr_size = HDR_OFFSET + HDR_FW_SIZE + sizeof(__be32);
 	size_t size = 0;
 	int rc;
 
@@ -851,9 +853,23 @@ static int load_copro_firmware(struct fsi_master_acf *master)
 	dev_dbg(master->dev, "Looking for image sig %04x\n", wanted_sig);
 
 	/* Try to find it */
-	for (data = fw->data; data < (fw->data + fw->size);) {
+	end = fw->data + fw->size;
+	for (data = fw->data; data < end;) {
+		if (end - data < image_hdr_size) {
+			dev_err(master->dev, "Truncated firmware image header\n");
+			rc = -EINVAL;
+			goto release_fw;
+		}
+
 		sig = be16_to_cpup((__be16 *)(data + HDR_OFFSET + HDR_SYS_SIG));
 		size = be32_to_cpup((__be32 *)(data + HDR_OFFSET + HDR_FW_SIZE));
+		if (size < image_hdr_size ||
+		    size > end - data) {
+			dev_err(master->dev, "Invalid firmware image size %zu\n", size);
+			rc = -EINVAL;
+			goto release_fw;
+		}
+
 		if (sig == wanted_sig)
 			break;
 		data += size;
-- 
